INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 13, 'theory', 'Quiz: nftables and firewalld');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 13, 0, 'A packet is accepted by an accept rule in the base chain input of table inet filter (priority 0). Another table has an input chain with priority 10 and policy drop, with no matching rules. What happens to the packet?', '["Accepted: accept cancels the other chains", "Accepted, because policy drop only applies to forward", "Dropped by the policy of the second chain", "Dropped, because the chain with priority 10 runs first"]', 2, 'Accept ends only its own base chain; the packet moves to the chain of the same hook with the larger priority number, where, with no rules, the drop policy applies. Priority sets the order: zero runs before ten.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 13, 1, 'A packet arrives on eth0 (zone public) from an address listed in the sources of zone internal. Which zone handles the packet by default?', '["internal: the source is checked before the interface", "public: the interface beats the source", "The default zone, it does not depend on the interface", "Both zones in turn"]', 0, 'firewalld looks for a zone by source first, then by interface, and only then takes the default zone. In newer versions a zone priority can change the order.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 13, 2, 'You loaded an input chain with policy drop and a single rule for port 22, without a ct state established rule. Your open SSH session is on port 2222. What happens?', '["The session keeps working: it is already established", "The policy discards the session''s packets to port 2222, the session hangs", "The kernel lets the session through until the tracking timeout expires", "The session switches to port 22 by itself"]', 1, 'Connection state allows nothing by itself: without a ct state established,related accept rule, the session''s packets that have no rule of their own fall under the drop policy.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 13, 3, 'In which hook does a masquerade rule make sense?', '["prerouting", "input", "forward", "postrouting"]', 3, 'Masquerade substitutes the address of the outgoing interface, so it is valid only in postrouting of a nat chain. Destination translation is done in prerouting.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 13, 4, 'Why should you not run nft flush ruleset on a hypervisor with firewalld and libvirt?', '["The command reboots the kernel", "It clears only the filter table", "It removes all tables, including those made by firewalld and libvirt, so their rules are gone until the services reload", "It disables the nf_tables module permanently"]', 2, 'According to the nft documentation, flush ruleset removes all tables and everything they contain. The rules of firewalld and the libvirt network must be restored by reloading those services.');
